// All data requests go to fixed public Steam endpoints. No saved feed, Cache API or DB fallback.
const GAMES=[[553850,'绝地潜兵 2'],[1091500,'赛博朋克 2077'],[250900,'以撒的结合：重生']];
const noStore={'Cache-Control':'no-store, no-cache, must-revalidate','CDN-Cache-Control':'no-store','Content-Type':'application/json; charset=utf-8'};
const cover=id=>`https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/${id}/header.jpg`;
const money=n=>'¥ '+(n/100).toFixed(2);
function validImage(value){try{const u=new URL(value);if(u.protocol==='https:'&&!u.port&&!u.username&&!u.password&&u.hostname==='image.gcores.com'&&/^\/[a-zA-Z0-9_-]+\.(jpg|jpeg|png|webp)$/i.test(u.pathname))return u.href;return u.protocol==='https:'&&!u.port&&!u.username&&!u.password&&['shared.st.dl.eccdnx.com','shared.fastly.steamstatic.com','shared.akamai.steamstatic.com','cdn.akamai.steamstatic.com','cdn.cloudflare.steamstatic.com','clan.fastly.steamstatic.com','clan.akamai.steamstatic.com','images.steamusercontent.com'].includes(u.hostname)&&/^\/(store_item_assets\/steam\/apps|steam\/apps|steamcommunity\/public\/images\/clans|images|ugc)\//.test(u.pathname)?u.href:''}catch{return ''}}
async function upstream(url,init={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),11000);try{return await fetch(url,{...init,signal:controller.signal,cf:{cacheTtl:-1,cacheEverything:false},headers:{'Cache-Control':'no-store, no-cache',...init.headers}})}finally{clearTimeout(timer)}}
async function json(url){const r=await upstream(url,{headers:{Accept:'application/json'}});if(!r.ok)throw Error('HTTP '+r.status);return r.json()}
function rssText(value){return String(value||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/&#(x[\da-f]+|\d+);/gi,(_,n)=>{const code=n[0].toLowerCase()==='x'?parseInt(n.slice(1),16):Number(n);return code>0&&code<=0x10ffff?String.fromCodePoint(code):''}).replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&').trim()}
function parseCommunity(xml){return [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map(m=>{const tag=name=>rssText(m[1].match(new RegExp('<'+name+'(?:\\s[^>]*)?>([\\s\\S]*?)<\\/'+name+'>','i'))?.[1]);const title=tag('title'),url=tag('link'),time=Date.parse(tag('pubDate'));if(!/^https:\/\/www\.gcores\.com\/articles\/\d+$/.test(url)||!title||!Number.isFinite(time)||/会员抽奖|会员专享/.test(title))return null;return {id:url,game:'社区与行业',title,url,publishedAt:new Date(time).toISOString(),date:new Date(time).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}),source:'机核 · 公开 RSS',author:tag('author'),body:tag('description').slice(0,120000),bodyFormat:'html',image:validImage(tag('thumb')),imageKind:'source',fetchedAt:new Date().toISOString()}}).filter(Boolean).sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt)).slice(0,8)}
async function fetchCommunity(){try{const r=await upstream('https://www.gcores.com/rss',{headers:{Accept:'application/rss+xml, application/xml'}});if(!r.ok)throw Error('HTTP '+r.status);const community=parseCommunity(await r.text());return {community,providers:[{name:'机核公开 RSS',status:'ok'}],fetchedAt:new Date().toISOString(),mode:'live'}}catch(e){return {community:[],providers:[status('机核公开 RSS',e)],fetchedAt:new Date().toISOString(),mode:'live'}}}
function status(name,e){console.warn('Source unavailable',name,e.name,String(e.message).slice(0,160));return {name,status:'unavailable',message:e.name==='TimeoutError'?'上游请求超时':String(e.message).slice(0,100)}}
function newsImage(contents,appid){const text=String(contents||'').replace(/\{STEAM_CLAN_IMAGE\}/g,'https://clan.fastly.steamstatic.com/images');const candidates=[...text.matchAll(/\[img\s+src=["']([^"']+)["']\]\[\/img\]|\[img\]([^\[]+)\[\/img\]|<img[^>]+src=["']([^"']+)["']/gi)].map(m=>m[1]||m[2]||m[3]);for(const c of candidates){const url=validImage(c.trim().replace(/&amp;/g,'&'));if(url)return {image:url,imageKind:'article'}}return {image:cover(appid),imageKind:'game'}}
async function fetchNews(appids=""){const selected=appids.split(",").filter(x=>/^[1-9][0-9]{0,8}$/.test(x)).slice(0,8).map(x=>[Number(x),"Steam / "+x]);const news=[],providers=[];await Promise.all((selected.length?selected:GAMES).map(async([appid,game])=>{try{const result=await json(`https://api.steampowered.com/ISteamNews/GetNewsForApp/v2/?appid=${appid}&count=5&maxlength=0&feeds=steam_community_announcements`);const items=result.appnews?.newsitems;if(!Array.isArray(items))throw Error('来源未返回新闻');const fetchedAt=new Date().toISOString();for(const n of items){let u;try{u=new URL(n.url)}catch{continue}if(u.protocol!=='https:')continue;news.push({id:String(n.gid),appid,game,title:n.title,url:u.href,date:new Date(n.date*1000).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}),publishedAt:new Date(n.date*1000).toISOString(),source:'开发者 Steam 公告',author:n.author||game+' 开发团队',body:String(n.contents||'').slice(0,120000),bodyFormat:'bbcode',fetchedAt,...newsImage(n.contents,appid)})}providers.push({name:'Steam News / '+appid,status:'ok',fetchedAt})}catch(e){providers.push(status('Steam News / '+appid,e))}}));news.sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt));return {news,providers,mode:'live',fetchedAt:new Date().toISOString()}}
async function fetchDeals(){const deals=[],providers=[];await Promise.all([...GAMES.map(async([appid,game])=>{try{const r=(await json(`https://store.steampowered.com/api/appdetails?appids=${appid}&cc=cn&l=schinese`))[appid],d=r?.data,p=d?.price_overview;if(!r?.success||p?.currency!=='CNY'||!Number.isInteger(p.final))throw Error('国区价格暂不可用');deals.push({appid,game,price:money(p.final),original:p.initial>p.final?money(p.initial):'',discount:p.discount_percent,currency:'CNY',image:validImage(d.header_image)||cover(appid),imageKind:'game',url:`https://store.steampowered.com/app/${appid}/`,fetchedAt:new Date().toISOString()});providers.push({name:'Steam Store / '+appid,status:'ok'})}catch(e){providers.push(status('Steam Store / '+appid,e))}}), (async()=>{try{const r=await json('https://store.steampowered.com/api/featuredcategories/?cc=cn&l=schinese');if(!Array.isArray(r.specials?.items))throw Error('未返回优惠列表');for(const d of r.specials.items){if(d.currency!=='CNY'||!d.discounted||!Number.isInteger(d.final_price))continue;deals.push({appid:d.id,game:d.name,price:money(d.final_price),original:d.original_price>d.final_price?money(d.original_price):'',discount:d.discount_percent,currency:'CNY',image:validImage(d.large_capsule_image)||validImage(d.header_image)||cover(d.id),imageKind:'game',url:`https://store.steampowered.com/app/${d.id}/`,expiresAt:d.discount_expiration?new Date(d.discount_expiration*1000).toISOString():null,fetchedAt:new Date().toISOString()})}providers.push({name:'Steam 当前特惠',status:'ok'})}catch(e){providers.push(status('Steam 当前特惠',e))}})()]);const unique=new Map();deals.sort((a,b)=>b.discount-a.discount).forEach(d=>{if(!unique.has(d.appid))unique.set(d.appid,d)});return {deals:[...unique.values()].slice(0,12),providers,mode:'live',region:'CN',fetchedAt:new Date().toISOString()}}
function parseCatalog(html,start=0){const items=[];for(const match of html.matchAll(/<a\b([^>]*class="search_result_row[^>]*|[^>]*data-ds-appid[^>]*)>([\s\S]*?)<\/a>/gi)){const attrs=match[1],body=match[2],id=attrs.match(/data-ds-itemkey="App_(\d+)"/)?.[1];if(!id)continue;const game=rssText(body.match(/<span class="title">([\s\S]*?)<\/span>/)?.[1]);if(!game)continue;const cents=body.match(/data-price-final="(\d+)"/)?.[1],discount=Number(body.match(/data-discount="(\d+)"/)?.[1]||0),original=rssText(body.match(/class="discount_original_price">([^<]*)</)?.[1]);const priceText=rssText(body.match(/class="discount_final_price">([^<]*)</)?.[1]);const free=/免费|Free to Play/i.test(body);const cny=priceText.includes('¥')||priceText.includes('￥');items.push({appid:Number(id),game,price:cents!==undefined&&cny?money(Number(cents)):free?'免费游玩':priceText||'价格暂不可用',priceCents:cents!==undefined&&cny?Number(cents):free?0:null,original:/[¥￥]/.test(original)?original:'',discount,currency:cny?'CNY':null,image:validImage(rssText(body.match(/<img[^>]+src="([^"]+)"/)?.[1]))||cover(id),imageKind:'game',url:`https://store.steampowered.com/app/${id}/`,position:start+items.length+1,fetchedAt:new Date().toISOString()})}return items}
async function fetchCatalog(params){const mode=['all','deals','top','combined'].includes(params.get('mode'))?params.get('mode'):'combined';const start=Math.max(0,Math.min(2400,Math.floor((Number(params.get('start'))||0)/25)*25));const sort=['Price_ASC','Price_DESC'].includes(params.get('sort'))?params.get('sort'):'';const term=(params.get('q')||'').trim().slice(0,80);const query=new URLSearchParams({start:String(start),count:'25',page:String(start/25+1),infinite:'1',cc:'cn',l:'schinese',category1:'998'});if((mode==='top'||mode==='combined')&&!sort&&!term)query.set('filter','topsellers');if(mode==='deals'||mode==='combined')query.set('specials','1');if(sort)query.set('sort_by',sort);if(term)query.set('term',term);try{const result=await json('https://store.steampowered.com/search/results/?'+query);if(typeof result.results_html!=='string')throw Error('商店未返回游戏列表');if(result.start!==undefined&&Number(result.start)!==start)throw Error('来源未返回请求的页码');const items=parseCatalog(result.results_html,start),total=Number(result.total_count)||0;if(sort)items.sort((a,b)=>a.priceCents===null?1:b.priceCents===null?-1:sort==='Price_ASC'?a.priceCents-b.priceCents:b.priceCents-a.priceCents);return {items,total,start,next:start+25,hasMore:start+25<total&&start<2400,mode,sort,q:term,providers:[{name:'Steam 国区商店检索',status:'ok'}],fetchedAt:new Date().toISOString()}}catch(e){return {items:[],total:0,start,next:start,hasMore:false,mode,providers:[status('Steam 国区商店检索',e)],fetchedAt:new Date().toISOString()}}}
async function sourceImage(url){let target=url;for(let i=0;i<3;i++){if(!validImage(target))throw Error('Unapproved image redirect');const referer=new URL(target).hostname==='image.gcores.com'?'https://www.gcores.com/':'https://store.steampowered.com/';const response=await upstream(target,{redirect:'manual',headers:{Referer:referer,Accept:'image/avif,image/webp,image/*'}});if(response.status>=300&&response.status<400){const location=response.headers.get('location');if(!location)throw Error('Image redirect without destination');target=new URL(location,target).href;continue}return response}throw Error('Too many image redirects')}
async function liveResponse(request){const u=new URL(request.url);if(request.method!=='GET')return new Response('Method not allowed',{status:405,headers:{Allow:'GET','Cache-Control':'no-store'}});if(u.pathname==='/api/core/status')return Response.json({persistent:false,mode:'preview'},{headers:noStore});if(u.pathname==='/api/guides'){const url='https://www.minecraft.net/zh-hans/minecraft-tips-for-beginners';try{const r=await upstream(url);if(!r.ok)throw Error();const html=await r.text();const tag=[...html.matchAll(/<meta[^>]*>/gi)].map(m=>m[0]).find(m=>/name=[\"']description[\"']/i.test(m));const summary=rssText(tag?.match(/content=[\"']([^\"']*)[\"']/i)?.[1]||'Minecraft 官方新手指南：基础玩法、生存与探索。');return Response.json({guides:[{title:'Minecraft 官方新手指南',game:'Minecraft',source:'Minecraft 官网',url,summary}],fetchedAt:new Date().toISOString()},{headers:noStore})}catch{return Response.json({guides:[],message:'官方攻略来源本次直连失败'},{headers:noStore})}}if(u.pathname==='/api/catalog'){const data=await fetchCatalog(u.searchParams);return Response.json(data,{status:data.providers[0].status==='ok'?200:502,headers:noStore})}if(u.pathname==='/api/health')return Response.json({status:'ok',mode:'live-no-store',runtime:'Cloudflare Pages'},{headers:noStore});if(u.pathname==='/api/news'||u.pathname==='/api/deals'||u.pathname==='/api/community'){const data=await (u.pathname.endsWith('/news')?fetchNews(u.searchParams.get("appids")||""):u.pathname.endsWith('/community')?fetchCommunity():fetchDeals());return Response.json(data,{status:data.providers.every(p=>p.status!=='ok')?502:200,headers:noStore})}if(u.pathname==='/api/feed'){const [n,d]=await Promise.all([fetchNews(),fetchDeals()]);return Response.json({...n,...d,news:n.news,providers:[...n.providers,...d.providers]},{status:!n.news.length&&!d.deals.length?502:200,headers:noStore})}if(u.pathname==='/api/media'){const url=validImage(u.searchParams.get('url'));if(!url)return new Response('Unsupported image',{status:400,headers:{'Cache-Control':'no-store'}});try{const r=await sourceImage(url);if(!r.ok||!r.headers.get('content-type')?.startsWith('image/'))throw Error('Image unavailable: HTTP '+r.status);const bytes=await r.arrayBuffer();if(bytes.byteLength>8*1024*1024)throw Error('Image too large');return new Response(bytes,{headers:{'Content-Type':r.headers.get('content-type'),'Cache-Control':'no-store','CDN-Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}})}catch(e){console.warn('Source image unavailable',e.name,String(e.message).slice(0,100));return new Response('Source image unavailable',{status:502,headers:{'Cache-Control':'no-store'}})}}return Response.json({error:'Not found'},{status:404,headers:noStore})}


// Cloudflare Pages advanced mode. ASSETS preserves native video Range/HEAD handling.
const VIDEO_FILES = {snaptic:'snaptic-trailer.mp4', player:'player-film.mp4'};
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname.startsWith('/api/video/')) {
      if (!['GET', 'HEAD'].includes(request.method)) return new Response('Method not allowed', {status:405, headers:{Allow:'GET, HEAD'}});
      const id = url.pathname.slice('/api/video/'.length);
      if (!Object.hasOwn(VIDEO_FILES, id)) return new Response('Video not found', {status:404});
      url.pathname = '/videos/' + VIDEO_FILES[id];
      url.search = '';
      return env.ASSETS.fetch(new Request(url, request));
    }
    if (url.pathname.startsWith('/api/')) return liveResponse(request);
    return env.ASSETS.fetch(request);
  }
};
